// Taxonomies for the 5 strategic domains
const taxonomy = {
  aiTools: [
    "generative ai", "genai", "large language model", "llm", "agentic ai", 
    "chatgpt", "google gemini", "github copilot", "replit", "lovable", 
    "relay.app", "openclaw", "ai agent", "ai agents"
  ],
  aiHacks: [
    "jailbreak", "prompt injection", "prompt smuggling", "hallusquatting", 
    "seo poisoning", "hexstrike", "zero-click", "jit exploit", "data poisoning", 
    "infostealer", "lumma", "vidar", "mcp exploit", "mcp exploits"
  ],
  trendingAiSeo: [
    "ai overview", "aio", "generative engine optimization", "geo", 
    "search generative experience", "sge", "semantic search", "topical authority", 
    "entity authority", "conversational search", "ai content detection", 
    "algorithm update", "data void"
  ],
  linkedinVibeCoding: [
    "vibe coding", "ai-assisted development", "natural language programming", 
    "automated code generation", "ai skill verification", "dynamic skill badge", 
    "talent acquisition ai", "ai-generated linkedin content", "thought leadership"
  ],
  coreSecurity: [
    "autonomous penetration testing", "attack path management", "zero-trust", 
    "machine-speed attack", "soar", "ai supply chain attack", 
    "adversarial hallucination", "social engineering", "data exfiltration"
  ]
};

const allKeywords = Object.values(taxonomy).flat();
const items = $input.all();
const filtered = [];
const seenTitles = new Set();

for (const item of items) {
  const json = item.json;
  const title = (json.title || '').trim();
  const desc = (json.contentSnippet || json.content || json.description || '').toLowerCase();
  const searchStr = (title + ' ' + desc).toLowerCase();

  if (seenTitles.has(title.toLowerCase())) continue;

  const matched = allKeywords.filter(k => searchStr.includes(k));
  if (matched.length > 0) {
    seenTitles.add(title.toLowerCase());

    // Image URL extraction subroutine
    let imageUrl = json.imageUrl || null;
    if (!imageUrl && (json.content || json.description)) {
      const imgMatch = (json.content || json.description).match(/<img[^>]+src=["']([^"']+)["']/i);
      if (imgMatch) imageUrl = imgMatch[1];
    }

    filtered.push({
      json: {
        title: title,
        link: json.link,
        pubDate: json.pubDate,
        summary: json.contentSnippet || json.description,
        matchedKeywords: matched,
        matchScore: matched.length,
        imageUrl: imageUrl
      }
    });
  }
}

if (filtered.length === 0) return [];

filtered.sort((a, b) => b.json.matchScore - a.json.matchScore);

const rotationBucket = Math.floor(Date.now() / (1000 * 60 * 60 * 3)) % filtered.length;
const chosen = filtered[rotationBucket];

return [chosen];

